def rgb_to_hw10(r, g, b):
    r, g, b = r / 255.0, g / 255.0, b / 255.0
    y = 0.299 * r + 0.587 * g + 0.114 * b
    cb = (b - y) / 1.772
    cr = (r - y) / 1.402
    return (int(round(64 + y * 876)), int(round(512 + cr * 896)), int(round(512 + cb * 896)))

def clip(v, lo, hi):
    return lo if v < lo else hi if v > hi else v

def fire_rgb(L, tint):
    """L = level / 100 (0 .. 1.27): black, dark red .. bright red, orange, yellow."""
    if L < 0.06:
        r, g, b = 2.0, 2.0, 1.0
    elif L < 0.5:
        r, g, b = 30 + 210 * (L - 0.06) / 0.44, 2.0, 1.0
        if tint:
            r, g = 3.0, 8 + 70 * (L - 0.06) / 0.44
    elif L < 0.72:
        r, g, b = 243.0, 118 * (L - 0.5) / 0.22, 1.0
    else:
        r, g, b = 250.0, 118 + 97 * clip((L - 0.72) / 0.18, 0, 1), 1.0
    if tint and L < 0.06:
        r, g = 1.0, 1.0
    return r, g, b

def band_rgb(t, jade):
    t = clip(t, 0.0, 1.0)
    if t <= 0.08:
        return (0.0, 0.0, 0.0)
    if jade:
        return (6 + 30 * t, 24 + 150 * t, 4 + 20 * t)
    return (30 + 210 * t, 2 + 4 * t, 1 + t)

def pal_rom():
    out = []
    for sel in range(4):
        for i in range(128):
            if sel < 2:
                rgb = fire_rgb(i / 100.0, sel == 1)
                if i >= 92:
                    rgb = (250.0, 215.0, 0.0)
            else:
                rgb = band_rgb(i / 127.0, sel == 3)
            y, u, v = rgb_to_hw10(*rgb)
            y = clip(64 + int(round((y - 64) * 16 / 13.0)), 64, 940)
            out.append(((y >> 2) << 16) | ((clip(u, 4, 1020) >> 2) << 8) | (clip(v, 4, 1020) >> 2))
    return out

def exr_rom():
    out = []
    for i in range(512):
        if i < 256:
            out.append(int(round(32768 * 2 ** (i / 256.0))) & 0xFFFF)
        elif i < 384:
            hw = i - 256
            out.append(int(round(4096.0 / max(hw, 1))))
        elif i < 448:
            out.append(stk_rom()[i - 384])
        else:
            out.append(gw_rom()[i - 448])
    return out

def sin_rom():
    import math
    return [int(round(90 * math.sin(2 * math.pi * i / 32.0))) for i in range(32)]

def hash16(v):
    """the pixel path's shift-add hash (16 bits)"""
    h = (v + (v << 5) + 0x5A3C) & 0xFFFF; h ^= h >> 7
    h = (h + (h << 3) + 0x9E37) & 0xFFFF; h ^= h >> 5
    h = (h + (h << 7)) & 0xFFFF; h ^= h >> 9
    return h

def th_rom():
    """tooth heights: 4 + 0..3 per 64-virtual-px tooth"""
    return [hash16((i << 4) | 7) >> 14 for i in range(32)]

def rnd_rom():
    """segment classes: 5 random bits per entry, index = (contour index + per-line block offset) & 255"""
    return [hash16((i << 4) | 9) >> 11 for i in range(256)]

def stk_rom():
    """left-edge streaks per streak index (0..63): {class (2): 0 off, 1 dim, 2 bright; length step (4)}"""
    out = []
    for i in range(64):
        hs = hash16((i << 4) | 3) >> 8
        hl = hash16((i << 4) | 5) >> 8
        cls = 0 if hs < 38 else (1 if hs < 102 else 2)
        out.append((cls << 4) | (hl >> 4))
    return out

def gw_rom():
    """ghost blob half-width (virtual px) by |row offset| 0..48 (0 beyond)"""
    return [(175 - ((v * v * 41) >> 10)) if v <= 48 else 0 for v in range(64)]

def tab_rom():
    return [(IDOL[j] << 9) | LINE[j] for j in range(1024)]

def knot_rom():
    out = []
    for (yc, h, g) in KNOTS:
        out.append((yc << 15) | ((h & 0x1FF) << 6) | g)
    return out

def vhd_table(name, typ, depth, width, vals, signed=False):
    lines = ["    type %s is array (0 to %d) of %s(%d downto 0);" % ("t_" + name.lower(), depth - 1, typ, width - 1),
             "    constant %s : %s := (" % (name, "t_" + name.lower())]
    items = []
    for v in vals:
        if signed:
            items.append("to_signed(%d, %d)" % (v, width))
        elif width % 4 == 0:
            items.append('x"%0*X"' % (width // 4, v))
        else:
            items.append('"' + format(v, "0%db" % width) + '"')
    per = 8
    for i in range(0, len(items), per):
        lines.append("        " + ", ".join(items[i:i + per]) + ("," if i + per < len(items) else ""))
    lines.append("    );")
    return "\n".join(lines)

def main():
    parts = ["-- Generated by effigy.py -- DO NOT EDIT.",
             "library ieee;", "use ieee.std_logic_1164.all;", "use ieee.numeric_std.all;", "",
             "package effigy_pkg is",
             vhd_table("C_EF_TAB", "std_logic_vector", 1024, 18, tab_rom()),
             vhd_table("C_EF_KNOT", "std_logic_vector", 256, 26, knot_rom() + [0] * 192),
             vhd_table("C_EF_SIN", "signed", 32, 8, sin_rom(), signed=True),
             vhd_table("C_EF_TH", "unsigned", 32, 2, th_rom()),
             vhd_table("C_EF_RND", "unsigned", 256, 8, rnd_rom()),
             vhd_table("C_EF_PAL", "std_logic_vector", 512, 24, pal_rom()),
             vhd_table("C_EF_EXR", "unsigned", 512, 16, exr_rom()),
             "end package effigy_pkg;", ""]
    with open(os.path.join(HERE, "effigy_pkg.vhd"), "w") as f:
        f.write("\n".join(parts))

if __name__ == "__main__":
    main()
